mapper.insert:
		SELECT FCINFO_SEQ.nextval
		FROM dual

insert into COMTNNTFCINFO (
	NTCN_NO
	,NTCN_SJ
	,NTCN_CN
	,NTCN_TM
	,RECI_CONFIRMATION
	,NTCN_TY
	,NTT_ID
	,BBS_ID
	,NTCN_CH_CONTECT
	,NTCN_CH_ID
	,MBER_ID
	,READ_YN
	,LINK_URL)
values(
	#{ntcnNo}
	,#{ntcnSj}
	,#{ntcnCn}
	,sysdate
	,'0'
	,#{ntcnTy}
	,#{nttId}
	,#{bbsId}
	,#{ntcnChContect}
	,#{ntcnChId}
	,#{mberId}
	,#{readYn}
	,#{linkUrl})

mapper.update:
UPDATE COMTNNTFCINFO
SET READ_YN = 'Y'
WHERE NTCN_NO = #{ntcnNo}
